llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Ribavirin, the closest analogue sharing the D-ribose and carboxamide-azole core, has an absolute oral bioavailability of 52% in patients, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "A second ribavirin dataset in HCV patients reports absolute bioavailability of 45–65%, confirming that this polar ribonucleoside is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Fludarabine, a polar purine nucleoside analogue, shows oral bioavailability of 51–65%, demonstrating that hydrophilic nucleosides can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Clofarabine, another nucleoside analogue, has oral bioavailability of 57.5%, reinforcing the pattern that nucleoside analogues with transporter-mediated absorption can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Viramidine, a close ribavirin analogue, has 66.1% oral bioavailability in humans, further supporting high F for the carboxamide riboside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levovirin, the L-ribose enantiomer of ribavirin, has only ~10% oral bioavailability, but its L-stereochemistry is not transferable to the D-ribose query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C41"],
      "claim": "Uridine, a D-ribose pyrimidine nucleoside, has low oral bioavailability (6–10%), but the query is an imidazole carboxamide riboside more closely related to ribavirin than to uridine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental evidence (ribavirin, similarity 0.56) shows absolute oral bioavailability around 45–65% in patients, and other D-ribonucleoside analogues (fludarabine, clofarabine, viramidine) also exceed 20%. Low-bioavailability examples are either L-nucleosides or structurally more distant pyrimidine nucleosides, so the positive evidence transfers better. Prediction: high.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for AICAR/acadesine.",
    "The closest analogue similarity is moderate (0.56).",
    "The effect of the 5-amino group on intestinal permeability and nucleoside transporter affinity is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

